<section class="panel expedicao-panel" data-tab-panel="recebimento" hidden>
    <div class="expedicao-heading"><div><h2>Confirmação de entrega</h2><p>Registre a assinatura do destinatário para comprovar a entrega ao cliente.</p></div></div>
    <div class="recebimento-layout">
        <div class="expedicao-table-wrap"><table class="data-table expedicao-table recebimento-table"><thead><tr><th>Pedido</th><th>Loja</th><th>Romaneio</th><th>Volumes</th><th>Expedido em</th><th></th></tr></thead><tbody>
        <?php if (!empty($aguardandoRecebimento)): foreach ($aguardandoRecebimento as $item): $pedidoRecebimento=$item['pedido']??[]; $lojaRecebimento=trim((string)($pedidoRecebimento['cliente_nome_fantasia']??''))?:trim((string)($pedidoRecebimento['cliente_razao_social']??'')); ?>
            <tr><td><strong><?= $esc($pedidoRecebimento['codigo']??'#'.($pedidoRecebimento['id']??0)); ?></strong></td><td><span class="recebimento-loja" title="<?= $esc($lojaRecebimento); ?>"><?= $esc($lojaRecebimento?:'Loja não identificada'); ?></span></td><td><?= $esc($item['romaneio']??'—'); ?></td><td><?= (int)($item['volumes']??1); ?></td><td><?php $dataRecebimentoExpedicao=!empty($item['data_expedicao'])?strtotime((string)$item['data_expedicao']):false; if($dataRecebimentoExpedicao): ?><span class="expedicao-date"><strong><?= date('Y-m-d',$dataRecebimentoExpedicao); ?></strong><small><?= date('H:i:s',$dataRecebimentoExpedicao); ?></small></span><?php else: ?>—<?php endif; ?></td><td><button type="button" class="button button-outline" data-select-recebimento="<?= (int)$item['id']; ?>">Entregar</button></td></tr>
        <?php endforeach; else: ?><tr><td colspan="6" class="expedicao-empty">Nenhuma entrega aguardando confirmação.</td></tr><?php endif; ?>
        </tbody></table></div>
        <aside class="recebimento-card"><h3>Comprovante de entrega</h3><p>Selecione o pedido e peça a assinatura do destinatário.</p>
            <form method="post" class="recebimento-form" data-base-action="<?= $esc($url('expedicao/recebimento')); ?>">
                <label><span>Pedido / romaneio</span><select name="expedicao_id" required><option value="">Selecione uma entrega</option><?php foreach(($aguardandoRecebimento??[]) as $item): $pedidoRecebimento=$item['pedido']??[]; ?><option value="<?= (int)$item['id']; ?>"><?= $esc(($pedidoRecebimento['codigo']??'#'.($pedidoRecebimento['id']??0)).' · '.($item['romaneio']??'—')); ?></option><?php endforeach; ?></select></label>
                <label><span>Responsável pelo recebimento</span><input type="text" name="recebedor_nome" maxlength="120" autocomplete="name" required placeholder="Nome de quem recebeu"></label>
                <label><span>Observação <small>(opcional)</small></span><textarea name="observacao_recebimento" maxlength="500" rows="3" placeholder="Informação adicional sobre a entrega"></textarea></label>
                <label class="recebimento-assinatura"><span>Assinatura do responsável</span><span class="signature-box"><canvas data-receipt-signature data-signature="recebimento"></canvas><button type="button" class="button button-outline signature-clear" data-clear-receipt>Limpar</button></span><input type="hidden" name="assinatura_recebedor" data-receipt-signature-value data-signature-value="recebimento"><small class="signature-hint">Assine com o mouse ou toque sobre a linha.</small></label>
                <button type="submit" class="button button-primary recebimento-submit"><svg viewBox="0 0 24 24"><path d="M20 6 9 17l-5-5"/></svg>Confirmar entrega</button>
            </form>
        </aside>
    </div>
</section>
<style>
.recebimento-layout{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(340px,.7fr);gap:18px;align-items:start}.recebimento-card{position:sticky;top:18px;padding:24px;border:1px solid color-mix(in srgb,var(--primary) 16%,var(--border));border-radius:24px;background:linear-gradient(155deg,#fff,color-mix(in srgb,var(--primary) 3%,#fff));box-shadow:0 18px 42px rgba(15,23,42,.08)}.recebimento-card h3{margin:0 0 5px}.recebimento-card>p{margin:0 0 18px;color:var(--text-muted)}.recebimento-form{display:grid;gap:14px}.recebimento-form label{display:grid;gap:7px;color:var(--text);font-size:.88rem;font-weight:800}.recebimento-form label small{color:var(--text-muted);font-weight:650}.recebimento-form input,.recebimento-form select,.recebimento-form textarea{width:100%;border:1px solid color-mix(in srgb,var(--text-muted) 38%,transparent);border-radius:13px;background:#fff;color:var(--text);font:inherit;font-weight:600;box-sizing:border-box}.recebimento-form input,.recebimento-form select{min-height:50px;padding:0 14px}.recebimento-form textarea{padding:12px 14px;resize:vertical}.recebimento-form :is(input,select,textarea):focus{outline:0;border-color:var(--primary);box-shadow:0 0 0 4px color-mix(in srgb,var(--primary) 13%,transparent)}.recebimento-submit{width:100%;min-height:48px;justify-content:center}.recebimento-submit svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2.4}.recebimento-table th,.recebimento-table td{text-align:center!important;vertical-align:middle!important}.recebimento-table thead th{font-size:10.6px!important}.recebimento-table tbody td{font-size:13px!important}.recebimento-loja{display:-webkit-box;max-width:170px;max-height:32px;margin:auto;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2;line-clamp:2;line-height:16px;overflow-wrap:anywhere}.recebimento-assinatura .signature-box{min-height:157px}.recebimento-assinatura canvas{display:block;width:100%;height:155px;touch-action:none}@media(max-width:980px){.recebimento-layout{grid-template-columns:1fr}.recebimento-card{position:static}}@media(max-width:650px){.recebimento-card{padding:18px}}
</style>
<style>.recebimento-table tbody td:not(:nth-child(2)){white-space:nowrap}.recebimento-table th:nth-child(2),.recebimento-table td:nth-child(2){width:170px;max-width:170px}.recebimento-table tbody td:nth-child(2){height:46px!important;padding-top:6px!important;padding-bottom:6px!important}.recebimento-loja{width:100%;height:32px!important;max-height:32px!important}.recebimento-loja.is-long{font-size:12px!important}.recebimento-loja.is-very-long{font-size:11px!important;line-height:15px!important}</style>
<script>
document.querySelectorAll('.recebimento-loja').forEach(loja=>{const tamanho=loja.textContent.trim().length;loja.classList.toggle('is-long',tamanho>34&&tamanho<=55);loja.classList.toggle('is-very-long',tamanho>55)});
(()=>{const form=document.querySelector('.recebimento-form');if(!form)return;const select=form.elements.expedicao_id,canvas=form.querySelector('[data-receipt-signature]'),hidden=form.querySelector('[data-receipt-signature-value]'),clear=form.querySelector('[data-clear-receipt]'),ctx=canvas.getContext('2d');let drawing=false,ink=false;const setAction=()=>{form.action=select.value?`${form.dataset.baseAction}/${encodeURIComponent(select.value)}`:form.dataset.baseAction};const resize=()=>{const image=hidden.value||'',rect=canvas.getBoundingClientRect(),ratio=devicePixelRatio||1;if(rect.width<10)return;canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);ctx.strokeStyle='#111827';ctx.lineWidth=2.2;ctx.lineCap='round';ctx.lineJoin='round';if(image){const source=new Image();source.onload=()=>ctx.drawImage(source,0,0,rect.width,rect.height);source.src=image}};const point=event=>{const rect=canvas.getBoundingClientRect();return{x:event.clientX-rect.left,y:event.clientY-rect.top}};select.addEventListener('change',setAction);document.querySelectorAll('[data-select-recebimento]').forEach(button=>button.addEventListener('click',()=>{select.value=button.dataset.selectRecebimento;setAction();select.focus();document.querySelector('.recebimento-card')?.scrollIntoView({behavior:'smooth',block:'center'})}));canvas.addEventListener('pointerdown',event=>{event.preventDefault();drawing=true;ink=true;const p=point(event);ctx.beginPath();ctx.moveTo(p.x,p.y);canvas.setPointerCapture(event.pointerId)});canvas.addEventListener('pointermove',event=>{if(!drawing)return;const p=point(event);ctx.lineTo(p.x,p.y);ctx.stroke()});const save=()=>{if(!drawing)return;drawing=false;if(ink)hidden.value=canvas.toDataURL('image/png')};canvas.addEventListener('pointerup',save);canvas.addEventListener('pointercancel',save);clear.addEventListener('click',()=>{ctx.clearRect(0,0,canvas.width,canvas.height);hidden.value='';ink=false});form.addEventListener('submit',event=>{setAction();if(!select.value||!hidden.value){event.preventDefault();window.showAppToast?.('Selecione a entrega e faça a assinatura do responsável.','error')}});requestAnimationFrame(resize);window.addEventListener('resize',resize);document.querySelector('[data-tab-target="recebimento"]')?.addEventListener('click',()=>requestAnimationFrame(resize))})();
</script>
